# Short story blurbs, written from the trip-file PDFs (meyda.education.gov.il) and catalog pages.
STORIES = {
1: "ירושלים – סיפור שאינו נגמר. מתצפית הר הצופים, דרך עמק צורים ונחל קדרון ועד הרובע היהודי: שלושת אלפי שנות בירה, מאז שדוד המלך הקים בה את ביתו ושלמה בנה בה את המקדש.",
2: "\"מי שלא ראה בניין הורדוס לא ראה בניין נאה מימיו\". הורדוס, השליט השנוי במחלוקת, פיאר את ירושלים ואת בית המקדש במפעלי בנייה אדירים – חומות הר הבית, הכותל ומגדל דוד.",
3: "\"טדי הוא ירושלים וירושלים היא טדי\". בעקבות טדי קולק, ראש העיר שעיצב את ירושלים החדשה – מבניין העירייה ההיסטורי, דרך פארק טדי ומשכנות שאננים ועד מוזיאון ישראל שהקים.",
4: "\"אם לארץ נשמה – הרי ירושלים נשמתה של ארץ ישראל\" (בן גוריון). מסע מעיר דוד, דרך הרובע היהודי ועד משכן הכנסת – מהבירה של דוד המלך לבירת מדינת ישראל.",
5: "מסלול נוף ושכונות: מהמרכז המסחרי בקריית היובל, דרך ואדי האסבסטונים – שיכוני העולים של שנות ה-50 – ובמורד אל הכפר הציורי עין כרם.",
6: "מהר הרצל, אתר ההנצחה הלאומי, יורדים בשביל לעין כרם וממשיכים בשביל ישראל עד סכר בית זית – מסע מסמלי הממלכתיות אל הטבע שבשולי העיר.",
7: "הרפתקאות צ'רלס וורן – קצין ההנדסה הבריטי שחפר בסתר מתחת לירושלים העתיקה במאה ה-19, מדד את כיפת הסלע בגניבה וגילה את הפיר שנקרא על שמו.",
8: "ב-1867 הגיע הסופר מרק טוויין לירושלים ותיאר אותה בספרו \"מסע תענוגות לארץ הקודש\" בעוקצנות ובהתפעלות. הולכים בעקבותיו בסמטאות העיר העתיקה.",
9: "מחזון למציאות: ב-1898 הגיע הרצל לירושלים כדי לפגוש את הקיסר וילהלם השני. מהתחנה הישנה, דרך הכותל ומגדל דוד ועד הר הרצל – \"אם תרצו, אין זו אגדה\".",
10: "ב-1881 עלה אליעזר בן-יהודה לירושלים והיה למחולל תחיית השפה העברית. בעקבות האיש שבדה מילים \"ממוחו הקודח\" – מהכותל ועד ביתו ברחוב אתיופיה.",
11: "מסלול ארוך לאורך הקו העירוני – הגבול שחצה את העיר בין 1948 ל-1967: מטיילת ארמון הנציב, דרך אבו תור והר ציון, על טיילת החומות ועד הכותל.",
12: "\"אנחנו יושבים על הרכס שצופה לעיר העתיקה...\" בעקבות מוטה גור והצנחנים במלחמת ששת הימים – מגבעת התחמושת, דרך שער האריות ועד הכותל: \"הר הבית בידינו\".",
13: "המאבק על ירושלים במלחמת העצמאות: הרובע היהודי הנצור ו\"ליל הפורצים\" בשער ציון, הקרבות על מנזר סן סימון בקטמון והגנת קיבוץ רמת רחל.",
14: "מים לירושלים בעקבות חזקיהו מלך יהודה, שחצב את נקבת השילוח לקראת המצור האשורי: מאמות המים בארמון הנציב, דרך ברכת הסולטן והחומה הרחבה ברובע היהודי ועד עיר דוד.",
15: "\"וילכוד דוד את מצודת ציון היא עיר דוד\". בעקבות דוד המלך, מייסד שושלת בית דוד – מטיילת ארמון הנציב, דרך הר ציון ועיר דוד ועד נקבת חזקיהו ומרכז דוידסון.",
16: "עליית שנות ה-50 והחיים על קו התפר: בעקבות סעדיה מרציאנו, ממייסדי הפנתרים השחורים, בשכונת מוסררה – לצד מעבר מנדלבאום ובית תורג'מן.",
17: "מבוכרה לירושלים: הרב שלמה מוסאיוף, גביר מבוכרה, מכר את ביתו ועלה לירושלים, שם היה ממייסדי שכונת הבוכרים המפוארת – \"יתנוססו ארמונים מפוארים\".",
18: "משפחת מיוחס – משפחה ותיקה שמסורתה נמשכת עד ימי שיבת ציון. חלוצים ופורצי דרך: מבית מיוחס בכפר השילוח, דרך משכנות שאננים ועד רחוב מיוחס ושערי צדק.",
19: "\"וכל מקום שם בירושלים קרוי משה...\" (עגנון). משה מונטיפיורי, הנדבן היהודי מאנגליה, הוציא את היהודים מחוץ לחומות – משכנות שאננים, טחנת הרוח, ימין משה ומזכרת משה.",
20: "יצחק נבון, הנשיא החמישי, נולד בירושלים ושזר בה \"סל תרבות\": משכונת אוהל משה שבה גדל, דרך בית הנשיא ועד חלקת גדולי האומה בהר הרצל.",
21: "ר' יוסף ריבלין – \"ר' יושעה בונה השכונות\" – יזם פרטי פורץ דרך שהוביל את היציאה מהחומות: נחלת שבעה, אבן ישראל, משכנות ישראל, מזכרת משה ועוד.",
22: "\"אני כמו עץ שתול, שורשיי נחים בין זיכרון יוסף לשכונת הפחים\". ירושלים של יוסי בנאי – קולנוע רקס, כיכר ציון, הסמטאות ובתי הכנסת של נחלאות.",
23: "הרב שלמה זלמן אויערבך, מגדולי הפוסקים של דורו, חי ופעל בשכונת שערי חסד. סיור בשכונות הצנועות שבהן לימד והשפיע.",
24: "הרב עמרם בלוי ייסד את \"נטורי קרתא\" – \"שומרי העיר\", שאינם מכירים במדינה הציונית. מבתי אונגרין, דרך מאה שערים ו\"כיכר השבת\" – ועד הקרבות על קולנוע אדיסון.",
25: "נתיבות חסד: הרבנית ברכה קאפח, \"אם החסד\" של ירושלים, חילקה בגדים, מזון וסיוע לאלפי משפחות – בלי לשאול לשמו של מי שביקש עזרה.",
26: "\"נבנה ויבנה העולם עמנו באהבת חינם\". הרב אברהם יצחק הכהן קוק, הרב הראשי הראשון – חיבור בין ירושלים של מעלה לירושלים של מטה.",
27: "\"גור בארץ הזאת\": הרב מרדכי אלתר, האדמו\"ר מגור, ומוסדות חסידות גור בירושלים – ישיבת \"שפת אמת\", תלמוד תורה \"עץ חיים\" והמרכז העולמי של חסידות בעלז.",
28: "\"קיימתם היום הזה את שבועת הדורות\". הרב שלמה גורן, הרב הצבאי הראשי שתקע בשופר בכותל ב-1967 ולימים הרב הראשי – בעקבות הרבנים ומוסד הרבנות בירושלים.",
29: "\"הצדיק הירושלמי\": רב אריה לוין, \"רב האסירים\", ביקר את אסירי המחתרות בכלא הבריטי ואהב כל אדם – מבתי ברוידא ועד מוזיאון אסירי המחתרות.",
30: "ציונות ברחביה: מצריף הנשיא יצחק בן צבי ובית החלוצות של רחל ינאית, דרך הגימנסיה העברית ובניין המוסדות הלאומיים ועד יד לוי אשכול.",
31: "יגאל ידין – מצביא, ארכאולוג ומדינאי. מביתו ברחביה, דרך היכל הספר שבו מוצגות המגילות שחקר, ועד הכנסת – רבדים של עבר והווה.",
32: "זאב וילנאי, \"מר ארץ ישראל\", חוקר ומורה דרך שכתב את \"מדריך ישראל\" ואגדות ארץ ישראל. מסלול בעקבות הסיפורים והאגדות שאסף בירושלים.",
33: "יצחק בן צבי – הנשיא השני וחוקר עדות ישראל. מארמון הנציב, דרך אבו תור ועד יד בן צבי ברחביה, שם חי בצריף צנוע.",
34: "מעמק הצבאים העירוני, דרך שכונות הקטמונים – שכונות העולים של שנות ה-50 – ועד פארק המסילה ומתחם התחנה הישנה.",
35: "מנחם בגין – מפקד האצ\"ל וראש הממשלה. ממוזיאון אסירי המחתרות, דרך בית פרומין (הכנסת הראשונה), ביתו הראשון ומלון המלך דוד ועד מרכז מורשת בגין.",
36: "\"רב לך דבר שפתיים, צא אל עולם העשייה\". יואל משה סלומון – ממייסדי פתח תקווה ומחלוצי העיתונות העברית בירושלים ואחד מבוני נחלת שבעה.",
37: "בן גוריון וירושלים: מבית ראש הממשלה ברחביה, דרך המוסדות הלאומיים ובית פרומין – משכנה הראשון של הכנסת – ועד משכן הכנסת בגבעת רם.",
38: "בדצמבר 1917 נכנס הגנרל אלנבי ברגל בשער יפו וסיים 400 שנות שלטון עות'מאני. מטיילת ארמון הנציב, דרך כיכר אלנבי ברוממה, הדואר המרכזי ובניין העירייה ועד גן העצמאות.",
39: "משואה לתקומה: עולים ניצולי שואה ומצפון אפריקה שהגיעו במלחמת העצמאות ונפלו בהגנת ירושלים. משכונת מלחה, דרך יד ושם ועד הר הרצל.",
40: "\"לחשוב מחוץ לחומה\": ישראל דב פרומקין, עורך \"החבצלת\" – העיתון המרכזי בארץ ישראל – וראשית העיתונות העברית בירושלים.",
41: "\"הלו, הלו, ירושלים מדברת\" – ב-1936 עלה לשידור רדיו ירושלים. מקול ירושלים לקול ישראל: ממלון פאלאס ועד רשות השידור, בעקבות משה חובב.",
42: "חיים יסקי, מנהל בית החולים הדסה, נהרג בטבח שיירת הדסה בדרך להר הצופים באפריל 1948. סיור בעקבות סיפורו ובעקבות הקרבות על הר הצופים.",
43: "הנרייטה סולד – \"אמא תרזה של הציונות\": מייסדת \"הדסה\", טיפות החלב, בית הספר לאחיות ועליית הנוער. מבתי אונגרין ועד בניין המוסדות הלאומיים.",
44: "בעקבות חלוצי הרפואה בירושלים: ד\"ר משה וולך, מייסד בית החולים שערי צדק – \"כל מה שעשיתי לא עשיתי אלא תוך מילוי חובתי כרופא\".",
45: "\"אני מאשים\": גדעון האוזנר, התובע במשפט אייכמן – \"עמדי ניצבים כאן שישה מיליון קטגורים\". מבית פרומין, דרך בית העם (מרכז ז'ראר בכר) ועד הכנסת.",
46: "בוריס שץ ייסד ב-1906 את בית הספר \"בצלאל\" – \"להוציא אמנות מציון\". מסלול של אמנות בצלאל ואמנות רחוב עכשווית, מרחוב בצלאל ועד שוק מחנה יהודה.",
47: "מנחם אוסישקין – מנהיג ציוני ויו\"ר הקרן הקיימת. מביתו \"בית מחניים\" ברחביה, דרך המוסדות הלאומיים ועד מערת ניקנור בהר הצופים, שם נקבר.",
48: "ממנורה למנורה: מהרובע היהודי והכותל, דרך גן העצמאות ומרכז העיר, אל קריית הלאום – בית המשפט העליון, הכנסת ומנורת הכנסת.",
49: "מימין משה למוסררה: מוזיאון הרכבל של מלחמת העצמאות, מרכז מורשת בגין, משכנות שאננים, כפר דוד – לאורך קו התפר הישן.",
50: "\"מורה משפיע על הנצח\". פרופ' דוד ילין – מחנך, חוקר עברית ממייסדי ועד הלשון ושכונת זיכרון משה, ומייסד המכללה הנושאת את שמו.",
51: "ש\"י עגנון, חתן פרס נובל לספרות, תיאר את ירושלים ב\"תמול שלשום\" ובסיפוריו. מסלול בעקבות הנופים והשכונות שבהם חי וכתב.",
52: "\"עבד של העיר הזאת\": המשורר יצחק שלו, שכתב את \"שירי ירושלים\" – מהגימנסיה העברית, דרך כיכר ציון ומגרש הרוסים ועד מוסררה.",
53: "\"מילים פורחות בירושלים\" – בעקבות המשורר יהודה עמיחי: מטיילת ארמון הנציב, דרך אבו תור וטחנת הרוח של מונטיפיורי ועד ברכת הסולטן ופארק טדי.",
54: "ראשית החינוך העברי בירושלים: חסיה סוקניק ייסדה גן ילדים עברי ראשון בעיר. בתי הספר למל, אוולינה דה רוטשילד, אליאנס ובצלאל – והמאבק על דמות החינוך.",
55: "\"עמדתי בתוך ירושלים המשובצת בשמש\". המשוררת זלדה – משכונת הבוכרים, דרך כרם אברהם ועד שערי חסד שבה חיה.",
56: "\"הכרתי את ירושלים בתקופותיה הטובות והרעות\". עוזי נרקיס, אלוף פיקוד מרכז במלחמת ששת הימים – ממחנה לוחמי תש\"ח ועד הכותל.",
57: "\"שיק ירושלמי\": קונרד שיק, אדריכל, ארכאולוג וחוקר גרמני שחי בעיר 55 שנה ותכנן את מאה שערים, בית תבור ומבנים רבים – ועד קברו בהר ציון.",
58: "אל-קודס: הח'ליף עומר בן אל-ח'טאב כבש את ירושלים ב-638 והחזיר אליה את היהודים. מג'בל אל-מוכבר, דרך כנסיית הקבר ומסגד עומר ועד הר הבית.",
59: "סיף א-דין תנכיז, מושל דמשק הממלוכי במאה ה-14, בנה בירושלים את מדרסת התנכיזיה, השוק והחאנים. מסלול באדריכלות הממלוכית ברובע המוסלמי.",
60: "סולימן המפואר, הסולטן העות'מאני, בנה את חומות ירושלים שאנו מכירים היום (1537–1541). ממוזיאון לאמנות האסלאם, דרך טלביה ועד החומה ושער יפו.",
61: "אנדרטאות יד ושם והשביל המחבר להר הרצל: מבקעת הקהילות ועמוד הגבורה, דרך חלקת גדולי האומה ועד האנדרטה לעולי אתיופיה.",
}

